package com.javalearn.lab.seckill.lab.cache;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.javalearn.lab.seckill.catalog.api.ProductResponse;
import com.javalearn.lab.seckill.catalog.cache.NullValueMarkerStore;
import com.javalearn.lab.seckill.catalog.cache.ProductAvalancheDefense;
import com.javalearn.lab.seckill.catalog.cache.ProductBloomFilterService;
import com.javalearn.lab.seckill.catalog.cache.ProductBreakdownDefense;
import com.javalearn.lab.seckill.catalog.cache.TtlJitter;
import com.javalearn.lab.seckill.catalog.cache.TwoLevelCacheManager;
import com.javalearn.lab.seckill.lab.api.CacheSeedResponse;
import com.javalearn.lab.seckill.lab.api.CacheStateResponse;
import com.javalearn.lab.seckill.lab.config.LabCacheAvalancheProperties;
import com.javalearn.lab.seckill.lab.config.LabCacheProperties;
import com.javalearn.lab.seckill.lab.toggle.CacheDefenseMode;
import com.javalearn.lab.seckill.lab.toggle.CacheDefenseModeService;
import com.javalearn.lab.seckill.lab.toggle.LabToggle;
import com.javalearn.lab.seckill.lab.toggle.LabToggleService;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.cache.Cache;
import org.springframework.cache.CacheManager;
import org.springframework.data.redis.core.ScanOptions;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;

import java.math.BigDecimal;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.Duration;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Objects;
import java.util.Set;

/**
 * Generates and observes the M4-1 cache experiment dataset (design section 8.4).
 *
 * <p>The dataset is {@code seed.product-count} products in the reserved id range
 * {@code [startId, startId + productCount - 1]}, the first
 * {@code seed.avalanche-key-count} of them warmed into L2 with one identical TTL
 * (the avalanche keys M4-2/M4-3 explode), and one designated hot key. The range
 * starts above {@code seed.protected-max-id}, so the Flyway demo products (1 and
 * 20, stock 100, zero orders) that {@code verify.sh}, {@code smoke.sh} and
 * {@code reset-lab.sh} assert on are never written.</p>
 *
 * <p>Seeding is idempotent: it inserts only the ids of the range that are still
 * missing, so calling it twice leaves exactly {@code productCount} rows and
 * reports {@code inserted=0}.</p>
 *
 * <p>Database writes run through {@link JdbcTemplate} without a transaction,
 * which keeps them on the write pool like {@code SeckillStockSeeder}. Redis and
 * Redisson work is best-effort: a Redis outage must not fail the seed, it must
 * show up as a smaller {@code avalancheKeysWritten} / {@code bloomInitialised=false}
 * so the operator knows the experiment is not set up yet.</p>
 */
public final class CacheExperimentDataService {

    private static final Logger log = LoggerFactory.getLogger(CacheExperimentDataService.class);

    /** Lets anyone tell an experiment row from a demo row when inspecting MySQL. */
    static final String EXPERIMENT_DESCRIPTION = "generated by POST /lab/cache/seed";

    private static final String SELECT_IDS_IN_RANGE =
            "SELECT id FROM catalog_product WHERE id BETWEEN ? AND ? ORDER BY id";
    private static final String SELECT_COUNT_IN_RANGE =
            "SELECT COUNT(*) FROM catalog_product WHERE id BETWEEN ? AND ?";
    private static final String SELECT_ROWS_IN_RANGE =
            "SELECT id, name, price, status, description FROM catalog_product"
                    + " WHERE id BETWEEN ? AND ? ORDER BY id";
    private static final String SELECT_ALL_IDS = "SELECT id FROM catalog_product ORDER BY id";
    private static final String INSERT_PRODUCT =
            "INSERT INTO catalog_product (id, name, price, status, description) VALUES (?, ?, ?, ?, ?)";

    private final LabCacheProperties properties;
    private final JdbcTemplate jdbcTemplate;
    private final StringRedisTemplate redisTemplate;
    private final ObjectMapper objectMapper;
    private final ProductBloomFilterService bloomFilter;
    private final NullValueMarkerStore markerStore;
    private final CacheDefenseModeService modeService;
    private final ProductBreakdownDefense breakdownDefense;
    private final ProductAvalancheDefense avalancheDefense;
    private final TtlJitter ttlJitter;
    private final LabCacheAvalancheProperties avalancheProperties;
    private final LabToggleService toggleService;
    private final CacheManager cacheManager;

    public CacheExperimentDataService(LabCacheProperties properties,
                                      JdbcTemplate jdbcTemplate,
                                      StringRedisTemplate redisTemplate,
                                      ObjectMapper objectMapper,
                                      ProductBloomFilterService bloomFilter,
                                      NullValueMarkerStore markerStore,
                                      CacheDefenseModeService modeService,
                                      ProductBreakdownDefense breakdownDefense,
                                      ProductAvalancheDefense avalancheDefense,
                                      TtlJitter ttlJitter,
                                      LabCacheAvalancheProperties avalancheProperties,
                                      LabToggleService toggleService,
                                      CacheManager cacheManager) {
        this.properties = Objects.requireNonNull(properties, "properties");
        this.jdbcTemplate = Objects.requireNonNull(jdbcTemplate, "jdbcTemplate");
        this.redisTemplate = Objects.requireNonNull(redisTemplate, "redisTemplate");
        this.objectMapper = Objects.requireNonNull(objectMapper, "objectMapper");
        this.bloomFilter = Objects.requireNonNull(bloomFilter, "bloomFilter");
        this.markerStore = Objects.requireNonNull(markerStore, "markerStore");
        this.modeService = Objects.requireNonNull(modeService, "modeService");
        this.breakdownDefense = Objects.requireNonNull(breakdownDefense, "breakdownDefense");
        this.avalancheDefense = Objects.requireNonNull(avalancheDefense, "avalancheDefense");
        this.ttlJitter = Objects.requireNonNull(ttlJitter, "ttlJitter");
        this.avalancheProperties = Objects.requireNonNull(avalancheProperties, "avalancheProperties");
        this.toggleService = Objects.requireNonNull(toggleService, "toggleService");
        this.cacheManager = Objects.requireNonNull(cacheManager, "cacheManager");
    }

    public CacheSeedResponse seed() {
        LabCacheProperties.Seed seed = properties.getSeed();
        long startId = seed.getStartId();
        long endId = startId + seed.getProductCount() - 1;
        long hotKeyId = startId + seed.getHotKeyIndex();

        Set<Long> present = new HashSet<>(
                jdbcTemplate.queryForList(SELECT_IDS_IN_RANGE, Long.class, startId, endId));
        List<Object[]> missing = new ArrayList<>();
        for (long id = startId; id <= endId; id++) {
            if (!present.contains(id)) {
                missing.add(new Object[] {
                        id,
                        seed.getNamePrefix() + "-" + (id - startId + 1),
                        seed.getPrice(),
                        seed.getStatus(),
                        EXPERIMENT_DESCRIPTION});
            }
        }
        int inserted = batchInsert(missing, seed.getWriteBatchSize());
        long rowsInRange = requiredCount(startId, endId);

        long avalancheKeys = 0L;
        boolean hotKeyWritten = false;
        try {
            avalancheKeys = warmAvalancheKeys(startId, seed.getAvalancheKeyCount(),
                    Duration.ofSeconds(seed.getAvalancheTtlSeconds()));
            hotKeyWritten = warmHotKey(hotKeyId, Duration.ofSeconds(seed.getHotKeyTtlSeconds()));
        } catch (RuntimeException ex) {
            log.warn("L2 experiment keys not warmed (Redis unavailable): {}", ex.toString());
        }

        long bloomIdsAdded = 0L;
        boolean bloomInitialised = false;
        try {
            bloomIdsAdded = bloomFilter.rebuild(jdbcTemplate.queryForList(SELECT_ALL_IDS, Long.class));
            bloomInitialised = bloomFilter.stats().initialised();
        } catch (RuntimeException ex) {
            log.warn("Bloom filter not rebuilt (Redisson unavailable): {}", ex.toString());
        }

        log.info("Cache experiment seed finished: range=[{},{}], inserted={}, present={},"
                        + " avalancheKeys={}, avalancheTtlSeconds={}, ttlJitter={}, hotKey={}, bloomIds={}",
                startId, endId, inserted, rowsInRange, avalancheKeys,
                seed.getAvalancheTtlSeconds(),
                modeService.current() == CacheDefenseMode.TTL_JITTER
                        ? "±" + avalancheProperties.getTtlJitter().getPercent() + "%"
                        : "off",
                hotKeyId, bloomIdsAdded);
        return new CacheSeedResponse(startId, endId, seed.getProductCount(), inserted,
                present.size(), rowsInRange, avalancheKeys, seed.getAvalancheTtlSeconds(),
                hotKeyId, hotKeyWritten, bloomIdsAdded, bloomInitialised,
                modeService.current().key());
    }

    public CacheStateResponse state() {
        LabCacheProperties.Seed seed = properties.getSeed();
        long startId = seed.getStartId();
        long endId = startId + seed.getProductCount() - 1;
        long hotKeyId = startId + seed.getHotKeyIndex();
        long rowsInRange = requiredCount(startId, endId);

        String l2Prefix = TwoLevelCacheManager.productL2KeyPrefix();
        Set<Long> l2Ids;
        boolean redisReachable = true;
        try {
            l2Ids = scanIds(l2Prefix);
        } catch (RuntimeException ex) {
            log.warn("L2 key scan failed (Redis unavailable): {}", ex.toString());
            l2Ids = Set.of();
            redisReachable = false;
        }
        long l2InRange = 0L;
        long avalancheAlive = 0L;
        for (long id = startId; id <= endId; id++) {
            if (!l2Ids.contains(id)) {
                continue;
            }
            l2InRange++;
            if (id < startId + seed.getAvalancheKeyCount()) {
                avalancheAlive++;
            }
        }

        long markers = redisReachable ? liveMarkerCount() : 0L;
        ProductBloomFilterService.Stats stats = bloomFilter.stats();

        return new CacheStateResponse(
                new CacheStateResponse.Defense(modeService.current().key(),
                        toggleService.isEnabled(LabToggle.CACHE)),
                breakdownView(),
                avalancheView(),
                new CacheStateResponse.Dataset(startId, endId, seed.getProductCount(), rowsInRange,
                        Math.max(0L, seed.getProductCount() - rowsInRange),
                        seed.getAvalancheKeyCount(), seed.getAvalancheTtlSeconds(), hotKeyId),
                new CacheStateResponse.Keys(redisReachable, countL1ExperimentKeys(startId, endId),
                        l2InRange, avalancheAlive, l2Ids.contains(hotKeyId)),
                new CacheStateResponse.Bloom(bloomFilter.key(), stats.initialised(), stats.size(),
                        stats.capacity(), stats.falseProbability()),
                new CacheStateResponse.NullCache(markerStore.keyPrefix(),
                        properties.getPenetration().getNullCache().getTtlSeconds(),
                        properties.getPenetration().getNullCache().getJitterSeconds(),
                        markers));
    }

    /**
     * The active breakdown strategy plus its parameters and live guard gauges;
     * the console reads this to show what is protecting the hot key right now.
     */
    private CacheStateResponse.Breakdown breakdownView() {
        CacheDefenseMode mode = modeService.current();
        LabCacheProperties.Mutex mutex = properties.getBreakdown().getMutex();
        LabCacheProperties.LogicalExpire logical = properties.getBreakdown().getLogicalExpire();
        return new CacheStateResponse.Breakdown(mode.key(),
                mode == CacheDefenseMode.MUTEX,
                mode == CacheDefenseMode.LOGICAL_EXPIRE,
                mutex.getWaitMs(), mutex.getLeaseMs(), mutex.getOnLockTimeout(),
                logical.getLogicalTtlSeconds(), logical.getRetentionSeconds(),
                logical.getRefreshPoolSize(), logical.getRefreshQueueCapacity(),
                breakdownDefense.staleEntries(), breakdownDefense.refreshInFlight());
    }

    /**
     * The active avalanche strategy plus its parameters and live guard gauges;
     * the console reads this to show what is protecting the product cache
     * against an L2 avalanche right now (design 8.4 雪崩 row).
     */
    private CacheStateResponse.Avalanche avalancheView() {
        CacheDefenseMode mode = modeService.current();
        LabCacheAvalancheProperties.TtlJitter jitter = avalancheProperties.getTtlJitter();
        LabCacheAvalancheProperties.L1Cache l1 = avalancheProperties.getL1Cache();
        LabCacheAvalancheProperties.DbFallback fallback = avalancheProperties.getDbFallback();
        return new CacheStateResponse.Avalanche(mode.key(),
                mode == CacheDefenseMode.TTL_JITTER, jitter.getPercent(),
                mode == CacheDefenseMode.L1_CACHE, l1.getRefreshIntervalSeconds(),
                l1.getStaleWindowSeconds(),
                avalancheDefense.l1StaleEntries(), avalancheDefense.l1RefreshInFlight(),
                mode == CacheDefenseMode.DB_FALLBACK, fallback.getPermits(),
                fallback.getPeriodMs(),
                avalancheDefense.limiterAcquired(), avalancheDefense.limiterRejected());
    }

    /**
     * Writes the avalanche keys with one identical TTL on purpose: M4-2/M4-3
     * need a set that expires in the same second to show the stampede, and the
     * null-cache markers must NOT be written this way.
     */
    private long warmAvalancheKeys(long startId, long count, Duration ttl) {
        if (count <= 0L) {
            return 0L;
        }
        long lastId = startId + count - 1;
        List<ProductRow> rows = jdbcTemplate.query(SELECT_ROWS_IN_RANGE, ProductRow.MAPPER,
                startId, lastId);
        for (ProductRow row : rows) {
            redisTemplate.opsForValue().set(l2Key(row.id()), toJson(row), ttl);
        }
        return rows.size();
    }

    private boolean warmHotKey(long hotKeyId, Duration ttl) {
        List<ProductRow> rows = jdbcTemplate.query(SELECT_ROWS_IN_RANGE, ProductRow.MAPPER,
                hotKeyId, hotKeyId);
        if (rows.isEmpty()) {
            return false;
        }
        redisTemplate.opsForValue().set(l2Key(rows.get(0).id()), toJson(rows.get(0)), ttl);
        return true;
    }

    private int batchInsert(List<Object[]> rows, int batchSize) {
        int inserted = 0;
        for (int from = 0; from < rows.size(); from += batchSize) {
            int to = Math.min(from + batchSize, rows.size());
            inserted += sumCounts(jdbcTemplate.batchUpdate(INSERT_PRODUCT, rows.subList(from, to)));
        }
        return inserted;
    }

    /**
     * {@code batchUpdate} reports a per-statement count, or
     * {@code SUCCESS_NO_INFO} (-2) on some drivers; a driver that does not
     * report still seeded its rows, so the caller uses {@code rowsInRange}.
     */
    private static int sumCounts(int[] counts) {
        int total = 0;
        for (int count : counts) {
            total += Math.max(count, 0);
        }
        return total;
    }

    private long requiredCount(long startId, long endId) {
        Long count = jdbcTemplate.queryForObject(SELECT_COUNT_IN_RANGE, Long.class, startId, endId);
        return count == null ? 0L : count;
    }

    private Set<Long> scanIds(String keyPrefix) {
        Set<Long> ids = new LinkedHashSet<>();
        ScanOptions options = ScanOptions.scanOptions()
                .match(keyPrefix + "*")
                .count(properties.getState().getScanCount())
                .build();
        try (var cursor = redisTemplate.scan(options)) {
            while (cursor.hasNext()) {
                String key = cursor.next();
                String suffix = key.substring(keyPrefix.length());
                try {
                    ids.add(Long.parseLong(suffix));
                } catch (NumberFormatException ignored) {
                    // A foreign key under the same prefix is not experiment data.
                }
            }
        }
        return ids;
    }

    private long countL1ExperimentKeys(long startId, long endId) {
        Cache productCache = cacheManager.getCache(TwoLevelCacheManager.PRODUCT_CACHE);
        Object nativeCache = productCache == null ? null : productCache.getNativeCache();
        if (!(nativeCache instanceof com.github.benmanes.caffeine.cache.Cache<?, ?> l1)) {
            // The cache toggle is off, so the manager hands out a NoOpCache:
            // there is no L1 to count and reporting 0 is the honest answer.
            return 0L;
        }
        long count = 0L;
        for (Object key : l1.asMap().keySet()) {
            if (key instanceof Long id && id >= startId && id <= endId) {
                count++;
            }
        }
        return count;
    }

    private long liveMarkerCount() {
        try {
            return scanIds(markerStore.keyPrefix()).size();
        } catch (RuntimeException ex) {
            log.warn("Null-cache marker scan failed (Redis unavailable): {}", ex.toString());
            return 0L;
        }
    }

    private String toJson(ProductRow row) {
        try {
            return objectMapper.writeValueAsString(new ProductResponse(
                    row.id(), row.name(), row.price(), row.status(), row.description()));
        } catch (com.fasterxml.jackson.core.JsonProcessingException ex) {
            throw new IllegalStateException("Experiment product " + row.id() + " is not serializable", ex);
        }
    }

    private static String l2Key(long id) {
        return TwoLevelCacheManager.productL2KeyPrefix() + id;
    }

    /** Minimal projection of a seeded row, reused by the L2 warm-up. */
    record ProductRow(long id, String name, BigDecimal price, String status, String description) {

        static final RowMapper<ProductRow> MAPPER = new RowMapper<>() {
            @Override
            public ProductRow mapRow(ResultSet rs, int rowNum) throws SQLException {
                return new ProductRow(rs.getLong("id"), rs.getString("name"),
                        rs.getBigDecimal("price"), rs.getString("status"),
                        rs.getString("description"));
            }
        };
    }
}
